-- _gen_e1a.sql : English Language 2000-2002 (qnum continues from 10)
insert into public.questions (subject_slug, topic_slug, year, qnum, stem, options, answer, explanation, kind, steps, difficulty) values
('english','lexis-structure',2000,10, $q$Fill each gap with the most appropriate option: Neither the captain nor the players ___ present at the victory party.$q$,
 $o$[{"label":"A","text":"was"},{"label":"B","text":"were"},{"label":"C","text":"is"},{"label":"D","text":"has"}]$o$,
 'B',
 $q$With 'neither ... nor', the verb agrees with the subject nearest to it ('the players', plural), so the plural verb is required.$q$,
 'single', null, 2),
('english','lexis-structure',2000,11, $q$Fill each gap with the most appropriate option: She ___ in Lagos since 1998 and has no plans to relocate.$q$,
 $o$[{"label":"A","text":"lives"},{"label":"B","text":"lived"},{"label":"C","text":"has lived"},{"label":"D","text":"is living"}]$o$,
 'C',
 $q$An action that began in the past and continues up to the present, introduced by 'since', takes the present perfect tense.$q$,
 'single', null, 1),
('english','lexis-structure',2000,12, $q$Fill each gap with the most appropriate option: Tunde has a flair ___ painting; his works sell quickly.$q$,
 $o$[{"label":"A","text":"on"},{"label":"B","text":"for"},{"label":"C","text":"in"},{"label":"D","text":"at"}]$o$,
 'B',
 $q$'Flair' collocates with 'for': 'a flair for' means a natural talent or aptitude for something.$q$,
 'single', null, 1),
('english','oral-forms',2000,13, $q$In some two-syllable words the stress shifts according to the part of speech. Which option is stressed on the first syllable when used as a noun and on the second syllable when used as a verb?$q$,
 $o$[{"label":"A","text":"record"},{"label":"B","text":"release"},{"label":"C","text":"offer"},{"label":"D","text":"garden"}]$o$,
 'A',
 $q$'Record' is RE-cord as a noun and re-CORD as a verb; 'release' is always stressed on the second syllable, while 'offer' and 'garden' keep first-syllable stress in all uses.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2000,14, $q$Choose the option opposite in meaning to the word in quotation marks: Dele is very "benevolent" to the poor.$q$,
 $o$[{"label":"A","text":"generous"},{"label":"B","text":"gentle"},{"label":"C","text":"cruel"},{"label":"D","text":"cheerful"}]$o$,
 'C',
 $q$'Benevolent' means kind and charitable, so its opposite is 'cruel'; the other options are near synonyms.$q$,
 'single', null, 1),
('english','lexis-structure',2000,15, $q$Fill each gap with the most appropriate option: A number of students ___ absent from the excursion.$q$,
 $o$[{"label":"A","text":"is"},{"label":"B","text":"was"},{"label":"C","text":"are"},{"label":"D","text":"has been"}]$o$,
 'C',
 $q$'A number of' + a plural noun is a plural subject and takes a plural verb; by contrast, 'the number of' is singular.$q$,
 'single', null, 2),
('english','lexis-structure',2000,16, $q$Fill each gap with the most appropriate option: The riot ___ out two days ago.$q$,
 $o$[{"label":"A","text":"has broken"},{"label":"B","text":"broke"},{"label":"C","text":"had broken"},{"label":"D","text":"breaks"}]$o$,
 'B',
 $q$'Ago' fixes the event at a definite point in finished past time, so the simple past tense is used.$q$,
 'single', null, 1),
('english','lexis-structure',2000,17, $q$Fill each gap with the most appropriate option: The new director is quite capable ___ managing the branch alone.$q$,
 $o$[{"label":"A","text":"of"},{"label":"B","text":"for"},{"label":"C","text":"in"},{"label":"D","text":"with"}]$o$,
 'A',
 $q$'Capable' takes the preposition 'of': capable of doing something.$q$,
 'single', null, 1),
('english','comprehension',2000,18, $q$Choose the option that best explains the information conveyed in the sentence: Wale is second to none in his class.$q$,
 $o$[{"label":"A","text":"Wale is the best student in his class."},{"label":"B","text":"Wale is not serious with his studies."},{"label":"C","text":"Wale came second in the last test."},{"label":"D","text":"Wale is the least brilliant in the class."}]$o$,
 'A',
 $q$'Second to none' means that nobody is better than him, i.e. he is the very best; it does not mean he occupies second position.$q$,
 'single', null, 1),
('english','antonyms-synonyms',2000,19, $q$Choose the option nearest in meaning to the word in quotation marks: The "abundant" harvest gladdened the farmers.$q$,
 $o$[{"label":"A","text":"scarce"},{"label":"B","text":"scanty"},{"label":"C","text":"meagre"},{"label":"D","text":"plentiful"}]$o$,
 'D',
 $q$'Abundant' means existing in large supply, which matches 'plentiful'; the other options express the opposite.$q$,
 'single', null, 1),
('english','oral-forms',2000,20, $q$Choose the question that the following sentence, with emphatic stress on the word in capital letters, answers: Uche LOVES Toyota cars.$q$,
 $o$[{"label":"A","text":"Does Uche hate Toyota cars?"},{"label":"B","text":"Does Ada love Toyota cars?"},{"label":"C","text":"Does Uche love Japanese cars?"},{"label":"D","text":"Does Uche drive Toyota cars?"}]$o$,
 'A',
 $q$Emphatic stress on the verb 'loves' contrasts it with its opposite, so the implied question is 'Does Uche hate Toyota cars?'$q$,
 'single', null, 2),
('english','lexis-structure',2000,21, $q$Fill each gap with the most appropriate option: Each of the finalists ___ a gold medal.$q$,
 $o$[{"label":"A","text":"were given"},{"label":"B","text":"was given"},{"label":"C","text":"have been given"},{"label":"D","text":"are given"}]$o$,
 'B',
 $q$'Each of' + a plural noun still refers to members one at a time, so the verb remains singular.$q$,
 'single', null, 2),
('english','lexis-structure',2000,22, $q$Fill each gap with the most appropriate option: If he had studied harder, he ___ the examination.$q$,
 $o$[{"label":"A","text":"would pass"},{"label":"B","text":"will pass"},{"label":"C","text":"had passed"},{"label":"D","text":"would have passed"}]$o$,
 'D',
 $q$This is a third conditional: the if-clause has the past perfect of an unreal past, so the main clause takes 'would have' + past participle.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2000,23, $q$Choose the option opposite in meaning to the word in quotation marks: The bulb is wrapped in a "transparent" material.$q$,
 $o$[{"label":"A","text":"opaque"},{"label":"B","text":"clear"},{"label":"C","text":"glossy"},{"label":"D","text":"slippery"}]$o$,
 'A',
 $q$'Transparent' means allowing light to pass through; 'opaque' means blocking light. 'Clear' is a synonym, not the opposite.$q$,
 'single', null, 1),
('english','oral-forms',2000,24, $q$Choose the option that rhymes with 'fever'.$q$,
 $o$[{"label":"A","text":"ever"},{"label":"B","text":"never"},{"label":"C","text":"weaver"},{"label":"D","text":"silver"}]$o$,
 'C',
 $q$'Fever' is /'fi:ve/, stressed on the first syllable, so the rhyme must match from the stressed vowel; 'weaver' alone shares /-i:ve/. 'Ever' and 'never' have short /e/ and 'silver' has short /i/.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2000,25, $q$Choose the option nearest in meaning to the word in quotation marks: The new term will "commence" next Monday.$q$,
 $o$[{"label":"A","text":"begin"},{"label":"B","text":"conclude"},{"label":"C","text":"pause"},{"label":"D","text":"shorten"}]$o$,
 'A',
 $q$'Commence' means to start or begin; it is often used of terms, ceremonies and proceedings.$q$,
 'single', null, 1),
('english','lexis-structure',2000,26, $q$Choose the option that best explains the information conveyed in the sentence: We were completely taken in by the trader's story.$q$,
 $o$[{"label":"A","text":"We were deceived by his story."},{"label":"B","text":"We were transported by the trader."},{"label":"C","text":"We were admitted into his house."},{"label":"D","text":"We were entertained by the story."}]$o$,
 'A',
 $q$'Take someone in' means to deceive or fool that person, which fits the sentence's complaint about the trader's story.$q$,
 'single', null, 2),
('english','comprehension',2000,27, $q$Choose the option that best completes the gap: Tunde is brilliant; ___, he failed the examination.$q$,
 $o$[{"label":"A","text":"moreover"},{"label":"B","text":"therefore"},{"label":"C","text":"consequently"},{"label":"D","text":"nevertheless"}]$o$,
 'D',
 $q$The second clause contrasts unexpectedly with the first ('brilliant' yet 'failed'), which calls for the contrastive connector 'nevertheless'; the other connectors express addition or result.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2000,28, $q$Choose the option opposite in meaning to the word in quotation marks: The new drug will "alleviate" the pain.$q$,
 $o$[{"label":"A","text":"aggravate"},{"label":"B","text":"relieve"},{"label":"C","text":"soothe"},{"label":"D","text":"lessen"}]$o$,
 'A',
 $q$'Alleviate' means to make suffering less severe; 'aggravate' means to make it worse. 'Relieve', 'soothe' and 'lessen' are synonyms.$q$,
 'single', null, 2),
('english','lexis-structure',2000,29, $q$Choose the option that best explains the information conveyed in the sentence: Rather than complain, the chairman took the bull by the horns and addressed the workers himself.$q$,
 $o$[{"label":"A","text":"He ran away from the problem."},{"label":"B","text":"He confronted the problem boldly."},{"label":"C","text":"He postponed the meeting indefinitely."},{"label":"D","text":"He blamed his secretary for the failure."}]$o$,
 'B',
 $q$'Take the bull by the horns' means to deal with a difficult situation directly and fearlessly.$q$,
 'single', null, 2),
('english','oral-forms',2000,30, $q$In some two-syllable words the stress shifts according to the part of speech. Which option is stressed on the first syllable when used as a noun and on the second syllable when used as a verb?$q$,
 $o$[{"label":"A","text":"advance"},{"label":"B","text":"permit"},{"label":"C","text":"slogan"},{"label":"D","text":"carbon"}]$o$,
 'B',
 $q$The noun is PERmit and the verb is perMIT; 'advance' keeps second-syllable stress as noun and verb, while 'slogan' and 'carbon' are nouns stressed on the first syllable only.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2000,31, $q$Choose the option nearest in meaning to the word in quotation marks: The "tenacious" student refused to quit even after three failures.$q$,
 $o$[{"label":"A","text":"timid"},{"label":"B","text":"feeble"},{"label":"C","text":"rash"},{"label":"D","text":"persistent"}]$o$,
 'D',
 $q$'Tenacious' means holding firm and refusing to give up, which matches 'persistent'; the others suggest weakness or carelessness.$q$,
 'single', null, 2),
('english','comprehension',2000,32, $q$Choose the option that best explains the information conveyed in the sentence: The quarrel over the seating arrangement was a storm in a teacup.$q$,
 $o$[{"label":"A","text":"It nearly destroyed the hall."},{"label":"B","text":"It was a fuss over a trivial matter."},{"label":"C","text":"It involved severe casualties."},{"label":"D","text":"It was settled by the principal."}]$o$,
 'B',
 $q$'A storm in a teacup' means unnecessary excitement or anger about something unimportant.$q$,
 'single', null, 1),
('english','oral-forms',2000,33, $q$Choose the option in which the two words have the same vowel sound.$q$,
 $o$[{"label":"A","text":"caught / court"},{"label":"B","text":"fair / fear"},{"label":"C","text":"bed / bird"},{"label":"D","text":"cool / coal"}]$o$,
 'A',
 $q$'Caught' and 'court' both contain the long vowel /o:/; 'fair' and 'fear' contrast /ea/ with /ie/, 'bed' and 'bird' contrast /e/ with /e:/, and 'cool' and 'coal' contrast /u:/ with /eu/.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2000,34, $q$Choose the option opposite in meaning to the word in quotation marks: The two elders failed to "concur" on the choice of a flag.$q$,
 $o$[{"label":"A","text":"agree"},{"label":"B","text":"disagree"},{"label":"C","text":"endorse"},{"label":"D","text":"approve"}]$o$,
 'B',
 $q$'Concur' means to agree or be of the same opinion, so its opposite is 'disagree'; the remaining options are synonyms.$q$,
 'single', null, 2),
('english','oral-forms',2000,35, $q$Choose the question that the following sentence, with emphatic stress on the word in capital letters, answers: The students FAILED the test.$q$,
 $o$[{"label":"A","text":"Did the teachers fail the students?"},{"label":"B","text":"Did the students attempt the test?"},{"label":"C","text":"Did the students pass the test?"},{"label":"D","text":"Did the students cheat in the test?"}]$o$,
 'C',
 $q$Emphatic stress on the verb 'failed' contrasts it with the opposite outcome 'pass', so the implied question is 'Did the students pass the test?'$q$,
 'single', null, 2),
('english','antonyms-synonyms',2000,36, $q$Choose the option nearest in meaning to the word in quotation marks: Climbing the peak was an "arduous" task.$q$,
 $o$[{"label":"A","text":"strenuous"},{"label":"B","text":"easy"},{"label":"C","text":"brief"},{"label":"D","text":"delicate"}]$o$,
 'A',
 $q$'Arduous' describes something demanding great effort, i.e. strenuous and laborious; 'easy' is its opposite.$q$,
 'single', null, 1),
('english','comprehension',2000,37, $q$In the sentence 'The bursar's dismissal of the cashier was abrupt and arbitrary,' the word 'arbitrary' suggests that the dismissal was$q$,
 $o$[{"label":"A","text":"based on careful investigation."},{"label":"B","text":"done without fair reason."},{"label":"C","text":"approved by the board."},{"label":"D","text":"postponed indefinitely."}]$o$,
 'B',
 $q$'Arbitrary' describes an action decided by personal whim or impulse rather than by any fair rule or established procedure.$q$,
 'single', null, 2);
insert into public.questions (subject_slug, topic_slug, year, qnum, stem, options, answer, explanation, kind, steps, difficulty) values
('english','lexis-structure',2001,10, $q$Fill each gap with the most appropriate option: A number of students ___ absent from the excursion.$q$,
 $o$[{"label":"A","text":"is"},{"label":"B","text":"was"},{"label":"C","text":"are"},{"label":"D","text":"has been"}]$o$,
 'C',
 $q$'A number of' + a plural noun is a plural subject and takes a plural verb; by contrast, 'the number of' takes a singular verb.$q$,
 'single', null, 2),
('english','lexis-structure',2001,11, $q$Fill each gap with the most appropriate option: If Bola ___ a car, he would drive us to school every day.$q$,
 $o$[{"label":"A","text":"has"},{"label":"B","text":"had"},{"label":"C","text":"will have"},{"label":"D","text":"is having"}]$o$,
 'B',
 $q$For an unreal condition in the present, the if-clause takes the past simple and the main clause takes 'would' + base verb (second conditional).$q$,
 'single', null, 2),
('english','lexis-structure',2001,12, $q$Fill each gap with the most appropriate option: Every confirmed worker is entitled ___ three weeks' paid leave.$q$,
 $o$[{"label":"A","text":"for"},{"label":"B","text":"with"},{"label":"C","text":"of"},{"label":"D","text":"to"}]$o$,
 'D',
 $q$'Entitled' is followed by the preposition 'to': entitled to a benefit or privilege.$q$,
 'single', null, 1),
('english','oral-forms',2001,13, $q$In some two-syllable words the stress shifts according to the part of speech. Which option is stressed on the first syllable when used as a noun and on the second syllable when used as a verb?$q$,
 $o$[{"label":"A","text":"literary"},{"label":"B","text":"fatal"},{"label":"C","text":"export"},{"label":"D","text":"entrance"}]$o$,
 'C',
 $q$'Export' is EX-port as a noun and ex-PORT as a verb; 'literary', 'fatal' and 'entrance' are not used as stress-shifting noun and verb pairs.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2001,14, $q$Choose the option nearest in meaning to the word in quotation marks: Water is "vital" to every living thing.$q$,
 $o$[{"label":"A","text":"essential"},{"label":"B","text":"trivial"},{"label":"C","text":"optional"},{"label":"D","text":"useless"}]$o$,
 'A',
 $q$'Vital' means absolutely necessary, which matches 'essential'; 'trivial', 'optional' and 'useless' express the opposite.$q$,
 'single', null, 1),
('english','lexis-structure',2001,15, $q$Fill each gap with the most appropriate option: The number of candidates ___ increased this year.$q$,
 $o$[{"label":"A","text":"have"},{"label":"B","text":"has"},{"label":"C","text":"are"},{"label":"D","text":"were"}]$o$,
 'B',
 $q$'The number of' + a plural noun refers to the figure itself, which is singular, so a singular verb is required.$q$,
 'single', null, 2),
('english','comprehension',2001,16, $q$Choose the option that best explains the information conveyed in the sentence: The two brothers are as different as chalk and cheese.$q$,
 $o$[{"label":"A","text":"They grew up in the same village."},{"label":"B","text":"They are completely unlike each other."},{"label":"C","text":"They admire each other."},{"label":"D","text":"They quarrel over family property."}]$o$,
 'B',
 $q$'As different as chalk and cheese' means totally different in nature or character, since chalk and cheese are unlike in colour, taste and use.$q$,
 'single', null, 1),
('english','lexis-structure',2001,17, $q$Fill each gap with the most appropriate option: By next month, the new building ___ completed.$q$,
 $o$[{"label":"A","text":"will have been"},{"label":"B","text":"would be"},{"label":"C","text":"had been"},{"label":"D","text":"has been"}]$o$,
 'A',
 $q$With 'by' + a future time, an action seen as finished before that time takes the future perfect tense.$q$,
 'single', null, 2),
('english','comprehension',2001,18, $q$Choose the option that best explains the information conveyed in the sentence: The chairman could not make head or tail of the audit report.$q$,
 $o$[{"label":"A","text":"The report had no headline."},{"label":"B","text":"He tore the report into two pieces."},{"label":"C","text":"He had no time to read the report."},{"label":"D","text":"He could not understand the report at all."}]$o$,
 'D',
 $q$'Make head or tail of' means to understand something; used negatively, it means to be completely unable to understand it.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2001,19, $q$Choose the option nearest in meaning to the word in quotation marks: The chairman's "concise" reply satisfied everyone.$q$,
 $o$[{"label":"A","text":"lengthy"},{"label":"B","text":"verbose"},{"label":"C","text":"wordy"},{"label":"D","text":"brief"}]$o$,
 'D',
 $q$'Concise' means expressing much in few words, i.e. brief; 'lengthy', 'verbose' and 'wordy' express the opposite.$q$,
 'single', null, 1),
('english','oral-forms',2001,20, $q$Choose the question that the following sentence, with emphatic stress on the word in capital letters, answers: Mary BAKED the cake.$q$,
 $o$[{"label":"A","text":"Did Ada bake the cake?"},{"label":"B","text":"Did Mary buy the cake?"},{"label":"C","text":"Did Mary eat the cake?"},{"label":"D","text":"Was the cake sold to Mary?"}]$o$,
 'B',
 $q$Emphatic stress on the verb 'baked' contrasts it with another verb, 'buy', so the implied question is 'Did Mary buy the cake?'$q$,
 'single', null, 2),
('english','lexis-structure',2001,21, $q$Fill each gap with the most appropriate option: The pupils are looking forward ___ the holidays.$q$,
 $o$[{"label":"A","text":"to"},{"label":"B","text":"for"},{"label":"C","text":"at"},{"label":"D","text":"on"}]$o$,
 'A',
 $q$The fixed expression is 'look forward to' + a noun or gerund, whatever the tense of 'look'.$q$,
 'single', null, 1),
('english','lexis-structure',2001,22, $q$Fill each gap with the most appropriate option: Not only the players but also the coach ___ responsible for the defeat.$q$,
 $o$[{"label":"A","text":"are"},{"label":"B","text":"were"},{"label":"C","text":"is"},{"label":"D","text":"have been"}]$o$,
 'C',
 $q$With 'not only ... but also', the verb agrees with the subject nearer to it, here the singular 'coach'.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2001,23, $q$Choose the option opposite in meaning to the word in quotation marks: The new manager is "arrogant" towards the staff.$q$,
 $o$[{"label":"A","text":"proud"},{"label":"B","text":"haughty"},{"label":"C","text":"humble"},{"label":"D","text":"conceited"}]$o$,
 'C',
 $q$'Arrogant' means proud and self-important; its opposite is 'humble'. 'Proud', 'haughty' and 'conceited' are synonyms.$q$,
 'single', null, 1),
('english','comprehension',2001,24, $q$Choose the option that best completes the gap: ___ his illness, Ali attended the lectures.$q$,
 $o$[{"label":"A","text":"Owing to"},{"label":"B","text":"Because of"},{"label":"C","text":"Despite"},{"label":"D","text":"Even if"}]$o$,
 'C',
 $q$The sentence states a concession (he came although he was ill), so 'Despite' + noun phrase is correct; 'owing to' and 'because of' would express cause, reversing the logic.$q$,
 'single', null, 2),
('english','lexis-structure',2001,25, $q$Fill each gap with the most appropriate option: By the time the police arrived, the thief ___. $q$,
 $o$[{"label":"A","text":"had fled"},{"label":"B","text":"has fled"},{"label":"C","text":"will flee"},{"label":"D","text":"flees"}]$o$,
 'A',
 $q$Of two past actions, the one completed earlier takes the past perfect: by the time of arrival, the fleeing had already occurred.$q$,
 'single', null, 1),
('english','oral-forms',2001,26, $q$In some two-syllable words the stress shifts according to the part of speech. Which option is stressed on the first syllable when used as a noun and on the second syllable when used as a verb?$q$,
 $o$[{"label":"A","text":"import"},{"label":"B","text":"insect"},{"label":"C","text":"artist"},{"label":"D","text":"system"}]$o$,
 'A',
 $q$'Import' is IM-port as a noun and im-PORT as a verb; 'insect', 'artist' and 'system' are simply nouns stressed on the first syllable.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2001,27, $q$Choose the option nearest in meaning to the word in quotation marks: The housekeeper's "meticulous" cleaning impressed the visitors.$q$,
 $o$[{"label":"A","text":"careless"},{"label":"B","text":"hasty"},{"label":"C","text":"clumsy"},{"label":"D","text":"painstaking"}]$o$,
 'D',
 $q$'Meticulous' means showing great care and attention to detail, which matches 'painstaking'; the others suggest the opposite.$q$,
 'single', null, 2),
('english','lexis-structure',2001,28, $q$Choose the option that best explains the information conveyed in the sentence: The rally has been put off till further notice.$q$,
 $o$[{"label":"A","text":"The rally has been postponed."},{"label":"B","text":"The rally has been cancelled."},{"label":"C","text":"The rally has ended."},{"label":"D","text":"The rally has been relocated."}]$o$,
 'A',
 $q$'Put off' means to postpone; 'till further notice' confirms a delay, not a cancellation (which would be 'called off').$q$,
 'single', null, 1),
('english','comprehension',2001,29, $q$Choose the option that best explains the information conveyed in the sentence: The old watchman kicked the bucket last night.$q$,
 $o$[{"label":"A","text":"He damaged a pail."},{"label":"B","text":"He celebrated his birthday."},{"label":"C","text":"He resigned at last."},{"label":"D","text":"He died."}]$o$,
 'D',
 $q$'Kick the bucket' is an informal idiom meaning to die; the literal reading is a distractor.$q$,
 'single', null, 1),
('english','antonyms-synonyms',2001,30, $q$Choose the option opposite in meaning to the word in quotation marks: "Diligent" students rarely fail examinations.$q$,
 $o$[{"label":"A","text":"hardworking"},{"label":"B","text":"lazy"},{"label":"C","text":"punctual"},{"label":"D","text":"obedient"}]$o$,
 'B',
 $q$'Diligent' means hardworking and careful, so its opposite is 'lazy'; 'punctual' and 'obedient' concern other qualities that are irrelevant here.$q$,
 'single', null, 1),
('english','lexis-structure',2001,31, $q$Choose the option that best explains the information conveyed in the sentence: By taking discipline first and rules last, the committee put the cart before the horse.$q$,
 $o$[{"label":"A","text":"It postponed the meeting twice."},{"label":"B","text":"It ended the discussion abruptly."},{"label":"C","text":"It got its priorities reversed."},{"label":"D","text":"It followed the natural sequence."}]$o$,
 'C',
 $q$'Put the cart before the horse' means to arrange things in the wrong or illogical order, reversing what should come first.$q$,
 'single', null, 2),
('english','oral-forms',2001,32, $q$Choose the option that rhymes with 'cable'.$q$,
 $o$[{"label":"A","text":"settle"},{"label":"B","text":"table"},{"label":"C","text":"battle"},{"label":"D","text":"kettle"}]$o$,
 'B',
 $q$'Cable' /'keibl/ and 'table' /'teibl/ share the stressed vowel /ei/ and the ending; 'settle', 'battle' and 'kettle' have short /a/ or /e/ before the final syllable.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2001,33, $q$Choose the option nearest in meaning to the word in quotation marks: Road blocks "impede" the flow of traffic.$q$,
 $o$[{"label":"A","text":"assist"},{"label":"B","text":"hinder"},{"label":"C","text":"hasten"},{"label":"D","text":"divert"}]$o$,
 'B',
 $q$'Impede' means to obstruct or hold up progress, which matches 'hinder'; 'assist' and 'hasten' express the opposite effect while 'divert' only changes direction.$q$,
 'single', null, 1),
('english','comprehension',2001,34, $q$Choose the option that best explains the information conveyed in the sentence: Everyone says Tunde is a chip off the old block.$q$,
 $o$[{"label":"A","text":"Tunde quarrels with his father."},{"label":"B","text":"Tunde closely resembles his father."},{"label":"C","text":"Tunde dislikes his father's trade."},{"label":"D","text":"Tunde inherited his uncle's land."}]$o$,
 'B',
 $q$'A chip off the old block' describes someone who is very like one of his parents in appearance or behaviour.$q$,
 'single', null, 1),
('english','oral-forms',2001,35, $q$Choose the option in which the two words have the same vowel sound.$q$,
 $o$[{"label":"A","text":"moon / blood"},{"label":"B","text":"put / book"},{"label":"C","text":"would / crowd"},{"label":"D","text":"move / stove"}]$o$,
 'B',
 $q$'Put' and 'book' both contain the short vowel /ʊ/; 'moon' has long /uː/ but 'blood' has short /ʌ/, 'would' has /ʊ/ but 'crowd' has /aʊ/, and 'move' has /uː/ while 'stove' has /əʊ/.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2001,36, $q$Choose the option opposite in meaning to the word in quotation marks: Efforts to "expand" the company's market failed last year.$q$,
 $o$[{"label":"A","text":"enlarge"},{"label":"B","text":"increase"},{"label":"C","text":"contract"},{"label":"D","text":"broaden"}]$o$,
 'C',
 $q$'Expand' means to make or become larger, so its opposite is 'contract' (shrink); the others are synonyms.$q$,
 'single', null, 1),
('english','oral-forms',2001,37, $q$Choose the question that the following sentence, with emphatic stress on the word in capital letters, answers: The chief arrived LATE.$q$,
 $o$[{"label":"A","text":"Did the chief arrive early?"},{"label":"B","text":"Did the chief arrive on time?"},{"label":"C","text":"Did the visitors arrive late?"},{"label":"D","text":"Did the chief leave early?"}]$o$,
 'A',
 $q$Emphatic stress on 'late' contrasts it with its opposite 'early', so the implied question is 'Did the chief arrive early?'$q$,
 'single', null, 2),
('english','antonyms-synonyms',2001,38, $q$Choose the option nearest in meaning to the word in quotation marks: The widow lived a "frugal" life.$q$,
 $o$[{"label":"A","text":"wasteful"},{"label":"B","text":"luxurious"},{"label":"C","text":"economical"},{"label":"D","text":"shabby"}]$o$,
 'C',
 $q$'Frugal' means sparing and careful with money, i.e. economical; 'wasteful' and 'luxurious' express the opposite while 'shabby' concerns appearance.$q$,
 'single', null, 1);
insert into public.questions (subject_slug, topic_slug, year, qnum, stem, options, answer, explanation, kind, steps, difficulty) values
('english','lexis-structure',2002,10, $q$Fill each gap with the most appropriate option: Neither of the two actresses ___ nominated for the award.$q$,
 $o$[{"label":"A","text":"were"},{"label":"B","text":"are"},{"label":"C","text":"was"},{"label":"D","text":"have been"}]$o$,
 'C',
 $q$'Neither of' + a plural noun is treated as singular in standard usage, so a singular verb is used.$q$,
 'single', null, 2),
('english','lexis-structure',2002,11, $q$Fill each gap with the most appropriate part of the correlative: Scarcely had the minister sat down ___ the alarm went off.$q$,
 $o$[{"label":"A","text":"than"},{"label":"B","text":"when"},{"label":"C","text":"that"},{"label":"D","text":"then"}]$o$,
 'B',
 $q$'Scarcely' combines with 'hardly' with 'when'; it is 'no sooner' that pairs with 'than'.$q$,
 'single', null, 2),
('english','lexis-structure',2002,12, $q$Fill each gap with the most appropriate option: After the scandal, the director resigned himself ___ his fate.$q$,
 $o$[{"label":"A","text":"to"},{"label":"B","text":"for"},{"label":"C","text":"on"},{"label":"D","text":"with"}]$o$,
 'A',
 $q$'Resign oneself to' means to accept an unpleasant situation without protest, and is fixed with the preposition 'to'.$q$,
 'single', null, 2),
('english','oral-forms',2002,13, $q$In some two-syllable words the stress shifts according to the part of speech. Which option is stressed on the first syllable when used as a noun and on the second syllable when used as a verb?$q$,
 $o$[{"label":"A","text":"confirm"},{"label":"B","text":"poignant"},{"label":"C","text":"present"},{"label":"D","text":"signal"}]$o$,
 'C',
 $q$'Present' is PRE-sent as a noun (a gift) and pre-SENT as a verb; 'confirm' is only a verb, 'poignant' only an adjective, and 'signal' keeps first-syllable stress as noun and verb.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2002,14, $q$Choose the option opposite in meaning to the word in quotation marks: It is "prudent" to save part of one's salary.$q$,
 $o$[{"label":"A","text":"thrifty"},{"label":"B","text":"reckless"},{"label":"C","text":"sensible"},{"label":"D","text":"careful"}]$o$,
 'B',
 $q$'Prudent' means careful and wise in handling matters, so its opposite is 'reckless'; the others are synonyms.$q$,
 'single', null, 1),
('english','lexis-structure',2002,15, $q$Fill each gap with the most appropriate option: Every man, woman and child ___ invited to the wedding.$q$,
 $o$[{"label":"A","text":"were"},{"label":"B","text":"are"},{"label":"C","text":"was"},{"label":"D","text":"have been"}]$o$,
 'C',
 $q$'Every' with singular nouns, even when coordinated, keeps the verb singular because it singles out each member.$q$,
 'single', null, 2),
('english','comprehension',2002,16, $q$Choose the option that best explains the information conveyed in the sentence: The goalkeeper is in hot water with the coach.$q$,
 $o$[{"label":"A","text":"He is taking a warm bath."},{"label":"B","text":"The coach is preparing soup for him."},{"label":"C","text":"He is admired by the coach."},{"label":"D","text":"He is in trouble with the coach."}]$o$,
 'D',
 $q$'In hot water' is an idiom meaning to be in trouble or in disgrace with authority.$q$,
 'single', null, 1),
('english','lexis-structure',2002,17, $q$Fill each gap with the most appropriate part of the correlative: The caretaker had no sooner locked the gate ___ the rain started.$q$,
 $o$[{"label":"A","text":"when"},{"label":"B","text":"than"},{"label":"C","text":"that"},{"label":"D","text":"then"}]$o$,
 'B',
 $q$'No sooner' is always completed by 'than'; 'scarcely' and 'hardly' are the partners of 'when'.$q$,
 'single', null, 2),
('english','comprehension',2002,18, $q$Choose the option that best explains the information conveyed in the sentence: Since the quarrel, the two families have been at daggers drawn.$q$,
 $o$[{"label":"A","text":"They hide weapons together."},{"label":"B","text":"They are openly hostile to each other."},{"label":"C","text":"They are on friendly terms."},{"label":"D","text":"They collect antique daggers."}]$o$,
 'B',
 $q$'At daggers drawn' describes enemies who are ready to fight, i.e. in open hostility towards each other.$q$,
 'single', null, 1),
('english','antonyms-synonyms',2002,19, $q$Choose the option nearest in meaning to the word in quotation marks: The committee's approval is only "tentative".$q$,
 $o$[{"label":"A","text":"final"},{"label":"B","text":"permanent"},{"label":"C","text":"provisional"},{"label":"D","text":"unanimous"}]$o$,
 'C',
 $q$'Tentative' means provisional or for the time being, subject to later change; 'final' and 'permanent' are opposites.$q$,
 'single', null, 2),
('english','oral-forms',2002,20, $q$Choose the question that the following sentence, with emphatic stress on the word in capital letters, answers: It RAINED in Lagos yesterday.$q$,
 $o$[{"label":"A","text":"Did rain fall in Ibadan yesterday?"},{"label":"B","text":"Did the sun shine in Lagos yesterday?"},{"label":"C","text":"Did it drizzle in Lagos yesterday?"},{"label":"D","text":"Did Lagos record rainfall today?"}]$o$,
 'B',
 $q$Emphatic stress on 'rained' contrasts it with another weather verb, 'shine', so the implied question is 'Did the sun shine in Lagos yesterday?'$q$,
 'single', null, 2),
('english','lexis-structure',2002,21, $q$Fill each gap with the most appropriate option: Despite repeated failures, the engineer was resolved ___ completing the project.$q$,
 $o$[{"label":"A","text":"on"},{"label":"B","text":"for"},{"label":"C","text":"about"},{"label":"D","text":"with"}]$o$,
 'A',
 $q$'Resolved on' + a gerund means being determined to do something; this sense of 'resolved' takes 'on'.$q$,
 'single', null, 2),
('english','lexis-structure',2002,22, $q$Fill each gap with the most appropriate option: Many a student ___ failed the entrance test.$q$,
 $o$[{"label":"A","text":"have"},{"label":"B","text":"has"},{"label":"C","text":"are"},{"label":"D","text":"were"}]$o$,
 'B',
 $q$'Many a' + a singular noun is grammatically singular even though the meaning is plural, so it takes a singular verb.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2002,23, $q$Choose the option nearest in meaning to the word in quotation marks: The governor gave a "candid" assessment of the economy.$q$,
 $o$[{"label":"A","text":"frank"},{"label":"B","text":"flattering"},{"label":"C","text":"insincere"},{"label":"D","text":"clever"}]$o$,
 'A',
 $q$'Candid' means open, sincere and straightforward, which matches 'frank'; the others suggest the opposite.$q$,
 'single', null, 1),
('english','comprehension',2002,24, $q$In the sentence 'The claim that a single herb cures every disease is spurious,' the word 'spurious' means$q$,
 $o$[{"label":"A","text":"popular"},{"label":"B","text":"expensive"},{"label":"C","text":"false"},{"label":"D","text":"natural"}]$o$,
 'C',
 $q$'Spurious' means not genuine or pretended, so the claim about the herb is false.$q$,
 'single', null, 2),
('english','lexis-structure',2002,25, $q$Fill each gap with the most appropriate option: My grandfather ___ smoke, but he gave it up last year.$q$,
 $o$[{"label":"A","text":"used to"},{"label":"B","text":"is used to"},{"label":"C","text":"was used to"},{"label":"D","text":"uses to"}]$o$,
 'A',
 $q$'Used to' + base verb expresses a habit that existed in the past but has stopped; 'be used to' takes a noun or gerund and means 'accustomed to'.$q$,
 'single', null, 2),
('english','oral-forms',2002,26, $q$In some two-syllable words the stress shifts according to the part of speech. Which option is stressed on the first syllable when used as a noun and on the second syllable when used as a verb?$q$,
 $o$[{"label":"A","text":"beacon"},{"label":"B","text":"burglar"},{"label":"C","text":"seminar"},{"label":"D","text":"object"}]$o$,
 'D',
 $q$'Object' is OB-ject as a noun (a thing) and ob-JECT as a verb (to protest); the others are nouns stressed on the first syllable.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2002,27, $q$Choose the option opposite in meaning to the word in quotation marks: The "reluctant" witness eventually testified.$q$,
 $o$[{"label":"A","text":"hesitant"},{"label":"B","text":"unwilling"},{"label":"C","text":"fearful"},{"label":"D","text":"willing"}]$o$,
 'D',
 $q$'Reluctant' means unwilling, so its opposite is 'willing'; 'hesitant' is a synonym and 'fearful' is unrelated.$q$,
 'single', null, 1),
('english','lexis-structure',2002,28, $q$Choose the option that best explains the information conveyed in the sentence: The handwriting was so poor that we could not make out the signature.$q$,
 $o$[{"label":"A","text":"We could not decipher the signature."},{"label":"B","text":"We could not produce the signature."},{"label":"C","text":"We refused to countersign the document."},{"label":"D","text":"The signature was a forgery."}]$o$,
 'A',
 $q$'Make out' means to manage to see, read or decipher something with difficulty.$q$,
 'single', null, 1),
('english','comprehension',2002,29, $q$Choose the option that best explains the information conveyed in the sentence: Bola could not help laughing when the clown stumbled.$q$,
 $o$[{"label":"A","text":"He offered help to the clown."},{"label":"B","text":"He laughed in spite of himself."},{"label":"C","text":"He was assisted in laughing."},{"label":"D","text":"He suppressed his laughter."}]$o$,
 'B',
 $q$'Cannot help doing something' means being unable to avoid or restrain oneself from doing it.$q$,
 'single', null, 1),
('english','antonyms-synonyms',2002,30, $q$Choose the option nearest in meaning to the word in quotation marks: The glow-worms made the bush path "luminous".$q$,
 $o$[{"label":"A","text":"dark"},{"label":"B","text":"noisy"},{"label":"C","text":"slippery"},{"label":"D","text":"bright"}]$o$,
 'D',
 $q$'Luminous' means giving out or reflecting light, i.e. bright; the other options do not fit.$q$,
 'single', null, 1),
('english','lexis-structure',2002,31, $q$Choose the option that best explains the information conveyed in the sentence: With three examinations scheduled for the same morning, Tunde was at his wit's end.$q$,
 $o$[{"label":"A","text":"He had plenty of time to spare."},{"label":"B","text":"He finished his work very early."},{"label":"C","text":"He did not know what to do."},{"label":"D","text":"He was highly amused."}]$o$,
 'C',
 $q$'At one's wit's end' means so puzzled or worried by difficulties that one does not know what to do next.$q$,
 'single', null, 2),
('english','oral-forms',2002,32, $q$Choose the option that rhymes with 'ever'.$q$,
 $o$[{"label":"A","text":"fever"},{"label":"B","text":"weaver"},{"label":"C","text":"never"},{"label":"D","text":"server"}]$o$,
 'C',
 $q$'Ever' /'eve/ rhymes with 'never' /'neve/; 'fever' and 'weaver' are stressed on the first syllable with the long vowel /i:/, and 'server' has the vowel /e:/.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2002,33, $q$Choose the option nearest in meaning to the word in quotation marks: The captain ordered the crew to "abandon" the sinking ship.$q$,
 $o$[{"label":"A","text":"board"},{"label":"B","text":"desert"},{"label":"C","text":"rescue"},{"label":"D","text":"repair"}]$o$,
 'B',
 $q$'Abandon' in this context means to leave or give up a place, i.e. to desert it; 'board' means to enter, the opposite action.$q$,
 'single', null, 1),
('english','comprehension',2002,34, $q$Choose the option that best completes the gap: The rains failed that season; ___, the harvest was very poor.$q$,
 $o$[{"label":"A","text":"nevertheless"},{"label":"B","text":"in addition"},{"label":"C","text":"consequently"},{"label":"D","text":"otherwise"}]$o$,
 'C',
 $q$The poor harvest is the result of the failed rains, so the result connector 'consequently' fits; the other connectors express contrast, addition or condition.$q$,
 'single', null, 1),
('english','oral-forms',2002,35, $q$Choose the option in which the two words have the same vowel sound.$q$,
 $o$[{"label":"A","text":"caught / cut"},{"label":"B","text":"heard / herd"},{"label":"C","text":"heart / hurt"},{"label":"D","text":"set / seat"}]$o$,
 'B',
 $q$'Heard' and 'herd' both contain the vowel /ɜː/; 'caught' has long /ɔː/ against 'cut' /ʌ/, 'heart' has long /ɑː/ against 'hurt' /ɜː/, and 'set' /e/ differs from 'seat' /iː/.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2002,36, $q$Choose the option opposite in meaning to the word in quotation marks: Planting ornamental trees will "enhance" the beauty of the campus.$q$,
 $o$[{"label":"A","text":"beautify"},{"label":"B","text":"magnify"},{"label":"C","text":"diminish"},{"label":"D","text":"advertise"}]$o$,
 'C',
 $q$'Enhance' means to increase or improve the value or quality of something, so its opposite is 'diminish' (reduce).$q$,
 'single', null, 1),
('english','oral-forms',2002,37, $q$Choose the question that the following sentence, with emphatic stress on the word in capital letters, answers: Ada sold her CAR.$q$,
 $o$[{"label":"A","text":"Did Ada sell the house?"},{"label":"B","text":"Did Ada buy the car?"},{"label":"C","text":"Did Bola sell the car?"},{"label":"D","text":"Did Ada repair the car?"}]$o$,
 'A',
 $q$Emphatic stress on 'car' contrasts the object sold with another possession ('house'), so the implied question is about the house.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2002,38, $q$Choose the option nearest in meaning to the word in quotation marks: The chief accepted our apology with "alacrity".$q$,
 $o$[{"label":"A","text":"reluctance"},{"label":"B","text":"suspicion"},{"label":"C","text":"promptness"},{"label":"D","text":"indignation"}]$o$,
 'C',
 $q$'Alacrity' means cheerful readiness and eagerness, expressed here by 'promptness'; the others describe an opposite attitude.$q$,
 'single', null, 2);
