-- _gen_e1b.sql : English Language 2003-2005 (qnum continues from 10)
insert into public.questions (subject_slug, topic_slug, year, qnum, stem, options, answer, explanation, kind, steps, difficulty) values
('english','lexis-structure',2003,10, $q$Fill each gap with the most appropriate option: The committee ___ a unanimous decision on the new rules.$q$,
 $o$[{"label":"A","text":"has taken"},{"label":"B","text":"have taken"},{"label":"C","text":"are taking"},{"label":"D","text":"were taken"}]$o$,
 'A',
 $q$A collective noun acting as one body takes a singular verb; a plural verb suits it only when the members are considered separately ('are divided').$q$,
 'single', null, 2),
('english','lexis-structure',2003,11, $q$Fill each gap with the most appropriate option: I wish I ___ in Jos to see the festival.$q$,
 $o$[{"label":"A","text":"am"},{"label":"B","text":"was"},{"label":"C","text":"were"},{"label":"D","text":"will be"}]$o$,
 'C',
 $q$After 'I wish' for an unreal present situation, the past subjunctive 'were' is preferred for all persons.$q$,
 'single', null, 2),
('english','lexis-structure',2003,12, $q$Fill each gap with the most appropriate option: Only the cashier is conversant ___ the daily sales figures.$q$,
 $o$[{"label":"A","text":"on"},{"label":"B","text":"in"},{"label":"C","text":"about"},{"label":"D","text":"with"}]$o$,
 'D',
 $q$'Conversant' takes the preposition 'with': conversant with matters or facts.$q$,
 'single', null, 1),
('english','oral-forms',2003,13, $q$In some two-syllable words the stress shifts according to the part of speech. Which option is stressed on the first syllable when used as a noun and on the second syllable when used as a verb?$q$,
 $o$[{"label":"A","text":"husband"},{"label":"B","text":"subject"},{"label":"C","text":"bicycle"},{"label":"D","text":"demand"}]$o$,
 'B',
 $q$'Subject' is SUB-ject as a noun (a topic) and sub-JECT as a verb; 'demand' keeps second-syllable stress as noun and verb, while 'husband' and 'bicycle' are first-syllable nouns only.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2003,14, $q$Choose the option opposite in meaning to the word in quotation marks: The inquiry "exonerated" the accused officer.$q$,
 $o$[{"label":"A","text":"acquitted"},{"label":"B","text":"pardoned"},{"label":"C","text":"convicted"},{"label":"D","text":"promoted"}]$o$,
 'C',
 $q$'Exonerate' means to clear someone of blame, so its opposite is 'convict'; 'acquit' and 'pardon' are synonyms.$q$,
 'single', null, 2),
('english','lexis-structure',2003,15, $q$Fill each gap with the most appropriate option: The jury ___ divided in their opinions after the first ballot.$q$,
 $o$[{"label":"A","text":"is"},{"label":"B","text":"was"},{"label":"C","text":"has"},{"label":"D","text":"are"}]$o$,
 'D',
 $q$Where a collective noun points to the separate members, shown here by 'their opinions', the plural verb is required.$q$,
 'single', null, 2),
('english','comprehension',2003,16, $q$Choose the option that best explains the information conveyed in the sentence: The valedictory service came off successfully.$q$,
 $o$[{"label":"A","text":"It was postponed at short notice."},{"label":"B","text":"It took place and ended well."},{"label":"C","text":"It was suspended."},{"label":"D","text":"It degenerated into a quarrel."}]$o$,
 'B',
 $q$'Come off' means to take place and succeed or go as planned; it does not refer to postponement or cancellation.$q$,
 'single', null, 1),
('english','lexis-structure',2003,17, $q$Fill each gap with the most appropriate option: I ___ what you are trying to say.$q$,
 $o$[{"label":"A","text":"understand"},{"label":"B","text":"am understanding"},{"label":"C","text":"was understanding"},{"label":"D","text":"had understood"}]$o$,
 'A',
 $q$Verbs of cognition such as 'understand', 'know' and 'believe' are stative and are not normally used in the continuous form.$q$,
 'single', null, 1),
('english','comprehension',2003,18, $q$In the sentence 'The director dismissed the clerk for asking redundant questions,' the word 'redundant' suggests that the questions were$q$,
 $o$[{"label":"A","text":"necessary."},{"label":"B","text":"useful."},{"label":"C","text":"interesting."},{"label":"D","text":"unnecessary."}]$o$,
 'D',
 $q$'Redundant' means superfluous, no longer needed, so the questions were uncalled for and excessive.$q$,
 'single', null, 2),
('english','antonyms-synonyms',2003,19, $q$Choose the option nearest in meaning to the word in quotation marks: The tax collector was "callous" in his demands.$q$,
 $o$[{"label":"A","text":"sympathetic"},{"label":"B","text":"generous"},{"label":"C","text":"heartless"},{"label":"D","text":"careless"}]$o$,
 'C',
 $q$'Callous' means cruelly indifferent to people's feelings, which matches 'heartless'; 'sympathetic' and 'generous' express the opposite.$q$,
 'single', null, 1),
('english','oral-forms',2003,20, $q$Choose the question that the following sentence, with emphatic stress on the word in capital letters, answers: The boy reads in the LIBRARY.$q$,
 $o$[{"label":"A","text":"Does the boy read in the classroom?"},{"label":"B","text":"Does the girl read in the library?"},{"label":"C","text":"Does the boy sleep in the library?"},{"label":"D","text":"Does the boy borrow books from the library?"}]$o$,
 'A',
 $q$Emphatic stress on the place 'library' contrasts it with another place, so the implied question asks whether he reads in a different room.$q$,
 'single', null, 2),
('english','lexis-structure',2003,21, $q$Fill each gap with the most appropriate option: In our firm, punctuality is synonymous ___ efficiency.$q$,
 $o$[{"label":"A","text":"to"},{"label":"B","text":"for"},{"label":"C","text":"between"},{"label":"D","text":"with"}]$o$,
 'D',
 $q$'Synonymous' is followed by 'with', meaning equivalent in meaning to something else.$q$,
 'single', null, 1),
('english','lexis-structure',2003,22, $q$Fill each gap with the most appropriate option: The teacher, as well as the students, ___ in the hall.$q$,
 $o$[{"label":"A","text":"was"},{"label":"B","text":"were"},{"label":"C","text":"are"},{"label":"D","text":"have been"}]$o$,
 'A',
 $q$A phrase such as 'as well as' or 'together with' does not change the number of the subject; the verb agrees with the first subject ('the teacher').$q$,
 'single', null, 2),
('english','antonyms-synonyms',2003,23, $q$Choose the option opposite in meaning to the word in quotation marks: The "vacant" post attracted many applicants.$q$,
 $o$[{"label":"A","text":"empty"},{"label":"B","text":"occupied"},{"label":"C","text":"deserted"},{"label":"D","text":"useless"}]$o$,
 'B',
 $q$'Vacant' means not occupied or filled, so its opposite is 'occupied'; 'empty' and 'deserted' are synonyms.$q$,
 'single', null, 1),
('english','comprehension',2003,24, $q$Choose the option that best explains the information conveyed in the sentence: The manager has decided to turn over a new leaf.$q$,
 $o$[{"label":"A","text":"He has ordered new files."},{"label":"B","text":"He has destroyed the old records."},{"label":"C","text":"He has resolved to change for the better."},{"label":"D","text":"He has resigned his appointment."}]$o$,
 'C',
 $q$'Turn over a new leaf' means to begin again with better behaviour, correcting one's past conduct.$q$,
 'single', null, 1),
('english','lexis-structure',2003,25, $q$Fill each gap with the most appropriate option: It is ten years since I last ___ my uncle.$q$,
 $o$[{"label":"A","text":"see"},{"label":"B","text":"had seen"},{"label":"C","text":"have seen"},{"label":"D","text":"saw"}]$o$,
 'D',
 $q$In the 'It is ... (time) since ...' construction, the event following 'since' is expressed in the simple past tense.$q$,
 'single', null, 2),
('english','oral-forms',2003,26, $q$In some two-syllable words the stress shifts according to the part of speech. Which option is stressed on the first syllable when used as a noun and on the second syllable when used as a verb?$q$,
