('english','lexis-structure',2004,15, $q$Fill each gap with the most appropriate option: Watching television ___ a favourite pastime of many children.$q$,
 $o$[{"label":"A","text":"are"},{"label":"B","text":"were"},{"label":"C","text":"is"},{"label":"D","text":"have been"}]$o$,
 'C',
 $q$A gerund phrase serving as subject ('watching television') is grammatically singular and takes a singular verb.$q$,
 'single', null, 2),
('english','lexis-structure',2004,16, $q$Fill each gap with the most appropriate option: The results ___ not been released yet.$q$,
 $o$[{"label":"A","text":"has"},{"label":"B","text":"is"},{"label":"C","text":"have"},{"label":"D","text":"had"}]$o$,
