insert into public.questions (subject_slug, topic_slug, year, qnum, stem, options, answer, explanation, kind, steps, difficulty) values
('english','lexis-structure',2006,10, $q$Fill each gap with the most appropriate option: The police ___ conducting investigations into the robbery.$q$,
 $o$[{"label":"A","text":"is"},{"label":"B","text":"are"},{"label":"C","text":"was"},{"label":"D","text":"has been"}]$o$,
